Using Knuth Morris Pratt Algorithm - O(n) Time and O(n) SpaceThe basic idea behind the approach is that we calculate the largest substring from the end and the length of the string minus this value is the minimum number of appends. The logic is intuitive, we need not append the palindrome and only those which do not form the palindrome. To find this largest palindrome from the end, we reverse the string, calculate the DFA.The DFA (Deterministic Finite Automaton) mentioned in the context of the Knuth Morris Pratt Algorithm is a concept used to help find the longest prefix of a string that is also a suffix and reverse the string again(thus gaining back the original string) and find the final state, which represents the number of matches of the string with the revered string and hence we get the largest substring that is a palindrome from the end.
            C++

    // CPP program for the given approach 
// using 2D vector for DFA
#include <bits/stdc++.h>

using namespace std;

// Function to build the DFA and precompute the state
vector<vector<int>> buildDFA(string& s) {
    int n = s.length();

  	// Number of possible characters (ASCII range)
    int c = 256; 

  	// Initialize 2D vector with zeros
    vector<vector<int>> dfa(n, vector<int>(c, 0)); 

    int x = 0;
    dfa[0][s[0]] = 1;

    // Build the DFA for the given string
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < c; j++) {
            dfa[i][j] = dfa[x][j];
        }
        dfa[i][s[i]] = i + 1;
        x = dfa[x][s[i]];
    }

    return dfa;
}

// Function to find the longest overlap
// between the string and its reverse
int longestOverlap(vector<vector<int>>& dfa, string& query) {
    int ql = query.length();
    int state = 0;

    // Traverse through the query to 
  	// find the longest overlap
    for (int i = 0; i < ql; i++) {
        state = dfa[state][query[i]];
    }
    return state;
}

// Function to find the minimum
// number of characters to append
int minAppends(string s) {

    // Reverse the string
    string reversedS = s;
    reverse(reversedS.begin(), reversedS.end());

    // Build the DFA for the reversed string
    vector<vector<int>> dfa = buildDFA(reversedS);

    // Get the longest overlap with the original string
    int longestOverlapLength = longestOverlap(dfa, s);

    // Minimum characters to append 
  	// to make the string a palindrome
    return s.length() - longestOverlapLength;
}

int main() {
    string s = "abede";
    cout << minAppends(s) << endl;
    return 0;
}


